import re
import subprocess

import pytest

PROJECT = "/project"

STRICT_RC = re.compile(
    r"^v(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)-rc\.([1-9]\d*)$"
)
LOOSE_RC = re.compile(r"rc", re.IGNORECASE)


def git(*args, check=True):
    proc = subprocess.run(
        ["git", "-c", "safe.directory=*", "-C", PROJECT, *args],
        capture_output=True,
        text=True,
    )
    if check and proc.returncode != 0:
        pytest.fail(f"git {' '.join(args)} failed: {proc.stderr.strip()}")
    return proc


def _tags():
    out = git(
        "for-each-ref",
        "--format=%(refname:strip=2)|%(objecttype)|%(*objecttype)|%(creatordate:unix)|%(*objectname)|%(objectname)",
        "refs/tags",
    ).stdout
    tags = []
    for line in out.splitlines():
        if not line.strip():
            continue
        name, otype, target_type, created, deref, obj = line.split("|")
        tags.append(
            {
                "name": name,
                "type": otype,
                "target_type": target_type,
                "created": int(created or 0),
                "commit": deref or obj,
            }
        )
    return tags


def _branches_containing(commit):
    out = git(
        "branch", "-a", "--contains", commit, "--format=%(refname:short)", check=False
    ).stdout
    return [b.strip() for b in out.splitlines() if b.strip()]


def _release_branches_exist():
    out = git(
        "for-each-ref", "--format=%(refname:short)", "refs/heads", "refs/remotes"
    ).stdout
    return [b for b in out.splitlines() if re.search(r"(^|/)release", b)]


def test_release_candidate_tags():
    check = git("rev-parse", "--git-dir", check=False)
    if check.returncode != 0:
        pytest.fail(f"{PROJECT} is not a readable git repository")

    tags = _tags()
    rc_tags = [t for t in tags if LOOSE_RC.search(t["name"]) and "-rc" in t["name"].lower()]
    if not rc_tags:
        pytest.skip("no release candidate has been cut yet (no -rc tags)")

    problems = []
    groups = {}

    for t in rc_tags:
        m = STRICT_RC.match(t["name"])
        if not m:
            problems.append(f"{t['name']}: does not match v<major>.<minor>.<patch>-rc.<N>")
            continue
        base = tuple(int(x) for x in m.groups()[:3])
        n = int(m.group(4))
        groups.setdefault(base, []).append((n, t))

        if t["type"] != "tag" or t["target_type"] != "commit":
            problems.append(f"{t['name']}: is not an annotated tag (object type {t['type']})")

    release_branches = _release_branches_exist()
    for base, items in groups.items():
        for n, t in items:
            containing = _branches_containing(t["commit"])
            if release_branches:
                on_release = [
                    b for b in containing if re.search(r"(^|/)release", b)
                ]
                if not on_release:
                    problems.append(
                        f"{t['name']}: commit not on any release branch "
                        f"(contained in: {containing or 'no branch'})"
                    )
            elif not containing:
                problems.append(f"{t['name']}: commit not reachable from any branch")

    for base, items in groups.items():
        ns = sorted(n for n, _ in items)
        expected = list(range(1, len(ns) + 1))
        label = "v%d.%d.%d" % base
        if ns != expected:
            problems.append(
                f"{label}: candidate numbers {ns} are not the contiguous sequence {expected}"
            )
            continue
        ordered = sorted(items, key=lambda x: x[0])
        for (n1, t1), (n2, t2) in zip(ordered, ordered[1:]):
            if t2["created"] < t1["created"]:
                problems.append(
                    f"{label}: rc.{n2} was created before rc.{n1}"
                )

    assert not problems, "Release candidate tag violations:\n" + "\n".join(problems)
